// Auto-assign crew based on availability and role
const events = $input.first().json.events;
const crew = $input.all()[1].json;

const assignments = [];

for (const event of events) {
  const eventDate = new Date(event.date);
  const requiredRoles = JSON.parse(event.requiredStaff);

  for (const [role, count] of Object.entries(requiredRoles)) {
    const availableCrew = crew.filter(c => 
      c.role === role && 
      c.availability.includes(eventDate.getDay())
    ).slice(0, count);

    for (const member of availableCrew) {
      assignments.push({
        eventId: event.id,
        eventName: event.name,
        userId: member.id,
        userName: member.name,
        userEmail: member.email,
        role: role,
        date: event.date
      });
    }
  }
}

return assignments.map(a => ({ json: a }));
